const routes=[{"title": "Прикус, мышцы и движение", "text": "Выберите роль, чтобы увидеть специалистов. План и состав команды определяются после консультации.", "roles": [{"label": "Функциональная стоматология", "person": {"name": "Зубачев Роман Николаевич", "role": "Директор, функциональный стоматолог", "exp": "Стаж 21 год", "url": "https://azmednsk.ru/team/zubachev-roman", "id": "person-0"}}, {"label": "Остеопатия", "person": {"name": "Старостенко Вадим Анатольевич", "role": "Врач-остеопат, заведующий отделением структуры", "exp": "Стаж 13 лет", "url": "https://azmednsk.ru/team/starostenko-vadim", "id": "person-2"}}, {"label": "Миофункциональная терапия", "person": {"name": "Лапина Наталья Сергеевна", "role": "Миофункциональный терапевт, немедицинский специалист", "exp": "Стаж 6 лет", "url": "https://azmednsk.ru/team/lapina-natalia", "id": "person-5"}}]}, {"title": "Пищеварение, питание и профилактика", "text": "Специалисты разных направлений могут участвовать в работе с вашим запросом.", "roles": [{"label": "Гастроэнтерология", "person": {"name": "Любаева Алена Юрьевна", "role": "Врач-терапевт превентивной и антивозрастной медицины, врач-гастроэнтеролог", "exp": "Стаж 17 лет", "url": "https://azmednsk.ru/team/lubaeva-alena", "id": "person-3"}}, {"label": "Нутрициология", "person": {"name": "Павлова Алла Викторовна", "role": "Нутрициолог", "exp": "Стаж 9 лет", "url": "https://azmednsk.ru/team/pavlova-anna", "id": "person-4"}}]}, {"title": "Сон, дыхание и функции полости рта", "text": "При жалобах на сон и дыхание состав обследования и участие специалистов определяются после консультации.", "roles": [{"label": "Функциональная стоматология", "person": {"name": "Зубачев Роман Николаевич", "role": "Директор, функциональный стоматолог", "exp": "Стаж 21 год", "url": "https://azmednsk.ru/team/zubachev-roman", "id": "person-0"}}, {"label": "Миофункциональная терапия", "person": {"name": "Лапина Наталья Сергеевна", "role": "Миофункциональный терапевт, немедицинский специалист", "exp": "Стаж 6 лет", "url": "https://azmednsk.ru/team/lapina-natalia", "id": "person-5"}}]}];function show(i){document.querySelectorAll('.tab').forEach((t,j)=>t.setAttribute('aria-selected',i===j));let r=routes[i];document.querySelector('#panel').innerHTML=`<div><h3>${r.title}</h3><p>${r.text}</p></div><div><div class="roles">${r.roles.map(x=>`<div class="role"><button type="button" aria-expanded="false">${x.label} ⌄</button><div class="tip"><strong>${x.person.name}</strong><p>${x.person.role}</p><a href="#${x.person.id}">Показать в команде ↓</a>${x.person.url?`<a href="${x.person.url}" target="_blank" rel="noopener">Подробнее о специалисте ↗</a>`:''}</div></div>`).join('')}</div><div class="peoplelinks">${r.roles.map(x=>`<a href="#${x.person.id}">${x.person.name.split(' ')[0]} ${x.person.name.split(' ')[1]} ↓</a>`).join('')}</div></div>`;document.querySelectorAll('.role>button').forEach(b=>b.onclick=()=>{let v=b.parentElement.classList.toggle('open');b.setAttribute('aria-expanded',v)})}document.querySelectorAll('.tab').forEach((b,i)=>b.onclick=()=>show(i));show(0);document.querySelector('input').oninput=e=>{let n=0;document.querySelectorAll('.person').forEach(p=>{p.hidden=!p.dataset.search.includes(e.target.value.toLowerCase().trim());if(!p.hidden)n++});document.querySelector('.empty').style.display=n?'none':'block'};document.addEventListener('click',e=>{let a=e.target.closest('a[href^="#person-"]');if(a){document.querySelector('input').value='';document.querySelectorAll('.person').forEach(p=>p.hidden=false);document.querySelector('.empty').style.display='none';document.querySelector(a.getAttribute('href'))?.focus({preventScroll:true})}});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.role.open').forEach(p=>{p.classList.remove('open');p.querySelector('button').blur()})});
document.addEventListener("click",e=>{if(!e.target.closest(".role"))document.querySelectorAll(".role.open").forEach(p=>{p.classList.remove("open");p.querySelector("button").setAttribute("aria-expanded","false")})});